/**
 * test/dist-staleness.test.js — the dist-staleness class-killer guard.
 *
 * Closes the deployed-artifact gap class the twin desk's live re-test
 * exposed (2026-06-07..2026-11: a deployed pre-shim dist bundle sat frozen
 * for five months while src moved). dist/index.js is generated by
 * tools/build-dist.js (`npm run build`), which stamps the sha256 of the
 * whole src/ tree into the artifact header. This test recomputes the
 * stamp from src/ and fails whenever the committed dist is stale
 * relative to src — the rebuild can no longer be forgotten silently.
 *
 * Also re-asserts the V1 shape contract here so it is enforced next to
 * the stamp: the payload re-export line stays byte-identical to the
 * pre-port file (md5 4fb46499ec2892e72943b63cf200b3f8, pinned by
 * d95ae9c) and dist keeps named-`server`-only, NO default export.
 *
 * Run: `npm test` (picked up by test/*.test.js glob) or
 *      `node --test test/dist-staleness.test.js`
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

import { computeSrcStamp, REEXPORT_LINE } from "../tools/build-dist.js";

const PLUGIN_ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const DIST_FILE = join(PLUGIN_ROOT, "dist", "index.js");

const STAMP_PREFIX = " * src-stamp: sha256:";

function readDist() {
  return readFileSync(DIST_FILE, "utf8");
}

function distStamp(dist) {
  const line = dist.split("\n").find((l) => l.startsWith(STAMP_PREFIX));
  return line ? line.slice(STAMP_PREFIX.length) : null;
}

test("staleness guard: dist carries a src-stamp header", () => {
  const stamp = distStamp(readDist());
  assert.notEqual(stamp, null, "dist/index.js has no src-stamp header — run `npm run build` (tools/build-dist.js) to rebuild it");
});

test("staleness guard: dist stamp matches recomputed src hash", () => {
  const dist = readDist();
  const stamped = distStamp(dist);
  assert.notEqual(stamped, null, "dist/index.js has no src-stamp header — run `npm run build`");
  const expected = computeSrcStamp();
  assert.equal(
    stamped,
    expected,
    "dist/index.js is STALE relative to src/ (stamped hash ≠ recomputed src hash) — run `npm run build` and commit the rebuilt artifact"
  );
});

test("staleness guard: payload re-export stays byte-identical to the pre-port file", () => {
  const dist = readDist();
  assert.ok(
    dist.endsWith(REEXPORT_LINE),
    `dist/index.js must end with the exact pre-port re-export payload: ${JSON.stringify(REEXPORT_LINE)}`
  );
});

test("staleness guard: dist stays named-server-only (no default export) while V1 is pinned", () => {
  const dist = readDist();
  assert.doesNotMatch(dist, /export\s+default/, "dist/index.js must NOT export a default while V1 1.18.31 is pinned (double-instantiation hazard)");
});
